import{_ as t,o as i,c as l,a3 as a}from"./chunks/framework.CRbjHCyB.js";const g=JSON.parse('{"title":"Lint","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Lint | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/zh/clice/cli/lint"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"zh_CN"}],["link",{"rel":"canonical","href":"https://docs.clice.io/zh/clice/cli/lint"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/clice/cli/lint"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/clice/cli/lint"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/clice/cli/lint"}]]},"headers":[],"relativePath":"zh/clice/cli/lint.md","filePath":"zh/clice/cli/lint.md","lastUpdated":1789451490000}'),c={name:"zh/clice/cli/lint.md"};function s(n,e,o,d,r,h){return i(),l("div",null,[...e[0]||(e[0]=[a(`<h1 id="lint" tabindex="-1">Lint <a class="header-anchor" href="#lint" aria-label="Permalink to &quot;Lint&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>clice 将 clang-tidy 集成为内置 Lint 引擎。<code>clice lint</code> 借助常驻 worker 池，对工作区内的翻译单元运行 <code>.clang-tidy</code> 中配置的检查，并输出一份合并后的报告。</p><p><strong>用法</strong>：<code>clice lint [--workspace &lt;dir&gt;] [--configuration &lt;tag&gt;] [--workers &lt;n&gt;] [--index]</code></p><p>对编译数据库中属于下文检查范围的每个翻译单元运行 clang-tidy， 输出合并后的检查结果；发现问题时以非零状态退出。 <code>--index</code> 还会利用同一批解析结果构建并持久化项目索引， 因此后续运行 <code>clice index</code> 时无需再执行任何操作。</p><p>退出码：<code>0</code> 表示检查通过，<code>1</code> 表示发现了问题，<code>2</code> 表示本次运行未能按要求完成——某个翻译单元运行失败，或索引未能持久化。运行被中断时退出码为 <code>130</code>。</p><h2 id="检查范围" tabindex="-1">检查范围 <a class="header-anchor" href="#检查范围" aria-label="Permalink to &quot;检查范围&quot;">​</a></h2><ul><li>编译数据库中列出、且位于工作区内的每个翻译单元。</li><li>被检查的单元所包含、且位于工作区内的每个头文件，并受 <code>.clang-tidy</code> 的头文件过滤项（<code>HeaderFilterRegex</code>、 <code>ExcludeHeaderFilterRegex</code>、<code>SystemHeaders</code>）约束，这些过滤项的读取方式与 clang-tidy 完全一致。</li><li>工作区之外的文件从不检查，无论构建是否把它们标记为系统头文件。<code>clice.toml</code> 中写有 <code>lint = false</code> 的规则也会把工作区内匹配到的文件排除在外，例如随项目附带的第三方库：</li></ul><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rules</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">patterns = [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;third_party/**&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">lint = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre></div><p>每个翻译单元从最近的 <code>.clang-tidy</code> 读取配置，继承方式与 clang-tidy 一致。所有文件中的 <code>NOLINT</code>、<code>NOLINTNEXTLINE</code> 以及 <code>NOLINTBEGIN</code>/<code>NOLINTEND</code> 注释都会生效。头文件会在每个包含它的翻译单元中被检查，这与 clang-tidy 的行为一致；若多个翻译单元报出完全相同的结果，连 note 也一样，该结果在报告中只出现一次；报告按文件和位置排序，并保留 clang-tidy 附加的 note。</p><h2 id="clang-tidy-集成质量" tabindex="-1">clang-tidy 集成质量 <a class="header-anchor" href="#clang-tidy-集成质量" aria-label="Permalink to &quot;clang-tidy 集成质量&quot;">​</a></h2><p>影响语言服务器中 clang-tidy 诊断质量的问题：</p><ul class="contains-task-list"><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 抑制系统头文件中宏产生的 clang-tidy 警告（<a href="https://github.com/clangd/clangd/issues/1587" target="_blank" rel="noreferrer">clangd#1587</a>、<a href="https://github.com/clangd/clangd/issues/2000" target="_blank" rel="noreferrer">clangd#2000</a>）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 对 Preamble 中的预处理指令（头文件保护、宏）执行检查（<a href="https://github.com/clangd/clangd/issues/2501" target="_blank" rel="noreferrer">clangd#2501</a>、<a href="https://github.com/clangd/clangd/issues/160" target="_blank" rel="noreferrer">clangd#160</a>）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 可按检查类别配置诊断严重级别（<a href="https://github.com/clangd/clangd/issues/1937" target="_blank" rel="noreferrer">clangd#1937</a>）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 支持加载 clang-tidy 插件（<a href="https://github.com/clangd/clangd/issues/1458" target="_blank" rel="noreferrer">clangd#1458</a>）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 支持 Clang 静态分析器（<a href="https://github.com/clangd/clangd/issues/905" target="_blank" rel="noreferrer">clangd#905</a>）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 应用 clang-tidy 修复时清理替换项（<a href="https://github.com/clangd/clangd/issues/429" target="_blank" rel="noreferrer">clangd#429</a>）</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 按版本控制差异过滤诊断（<a href="https://github.com/clangd/clangd/issues/822" target="_blank" rel="noreferrer">clangd#822</a>）</li><li class="task-list-item"><input class="task-list-item-checkbox" checked="" disabled="" type="checkbox"> 通过 NOLINT / NOLINTNEXTLINE / NOLINTBEGIN-END 注释抑制诊断</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> <code>.clangd</code> 配置中的 <code>Diagnostics.ClangTidy</code> 配置项</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 用于提升 clang-tidy 性能的快速检查过滤</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 将 clang-tidy 的 fix-it 建议作为代码操作</li><li class="task-list-item"><input class="task-list-item-checkbox" disabled="" type="checkbox"> 诊断元数据：检查名称、文档 URL、来源标签</li></ul>`,13)])])}const k=t(c,[["render",s]]);export{g as __pageData,k as default};
